        buildRunIndexColumn(context, 'requestIndex', 'Request', REQUEST_INDEX_COLUMN_WIDTH),
      ),
      ...buildRunColumns(runs, hideHighlights, (context) =>
        buildRunIndexColumn(context, 'turnIndex', 'Turn', TURN_INDEX_COLUMN_WIDTH),
