      return {
        ...metricGroup,
        children: [
          ...wrapRunLeaves(leaves, `${groupKey}_${metricKey}`, runs),
          wrapPanelLeaf(findLeafByColId(leaves, `delta_${groupKey}_${metricKey}`), DEFAULT_COMPARE_DELTA_HEADER),
        ],
