'use client';

import { FC } from 'react';
import { ColDef, IHeaderParams } from 'ag-grid-community';
import classNames from 'classnames';
import { EllipsisTooltip } from '@epam/ai-dial-ui-kit';

import { GridColumnType } from '@/src/types/grid-column';

interface Props extends IHeaderParams {
  isRightAligned?: boolean;
}

const hasRightAlignedType = (colDef?: ColDef | null): boolean => {
  const type = colDef?.type;
  return Array.isArray(type) ? type.includes(GridColumnType.RightAligned) : type === GridColumnType.RightAligned;
};

/**
 * Rendered inside the kit's header text node, which uppercases and letter-spaces its content, so the
 * label resets both. Without an explicit `isRightAligned` it follows the column: a right-aligned column
 * gets a right-aligned label over its values.
 */
const EllipsisHeader: FC<Props> = ({ displayName, isRightAligned, column }) => (
  <EllipsisTooltip
    text={displayName}
    className={classNames(
      'min-w-0 max-w-full dial-small-semi-text text-secondary normal-case tracking-normal',
      (isRightAligned ?? hasRightAlignedType(column?.getColDef())) && 'text-right',
    )}
    contentClassName="truncate"
  />
);

export default EllipsisHeader;
